1	package scan
2	
3	import (
4		"bufio"
5		"bytes"
6		"context"
7		"errors"
8		"fmt"
9		"io"
10		"log"
11		"os"
12		"path"
13		"path/filepath"
14		"regexp"
15		"strings"
16	
17		"gopkg.in/yaml.v3"
18	
19		"github.com/anthnel/devdesk/internal/k8s"
20	)
21	
22	// A Helm chart or a Kustomize overlay is validated after it is rendered
23	// (§3.80). Both renderers are optional: without them the directory is
24	// reported as not rendered, never as clean, and never as a missing tool —
25	// the schema stage did all it could.
26	//
27	// Measured on helm v4.3.0's sources (pkg/cmd/lint.go and
28	// pkg/chart/v2/lint/support/message.go) and kustomize v5.8.1's Dockerfile:
29	// alpine/helm's entrypoint is `helm`, the kustomize image's is
30	// /app/kustomize, so in both the arguments follow the image name.
31	
32	// Default images for the two renderers.
33	const (
34		DefaultHelmImage      = "alpine/helm"
35		DefaultKustomizeImage = "registry.k8s.io/kustomize/kustomize:v5.8.1"
36	)
37	
38	// IDs of the findings the renderers themselves produce.
39	const (
40		// HelmLintID is a message helm lint reported, at WARNING or ERROR.
41		HelmLintID = "HELM-LINT"
42		// K8sRenderID is a chart or an overlay that did not render at all.
43		K8sRenderID = "K8S-RENDER"
44	)
45	
46	// helmLintLine is one message of helm lint: `[SEVERITY] path: message`, as
47	// support.Message.Error formats it.
48	var helmLintLine = regexp.MustCompile(`^\[(ERROR|WARNING|INFO|UNKNOWN)\] ([^:]*): (.*)$`)
49	
50	// helmSourceLine is the comment helm template writes above each document,
51	// naming the template it came from: `# Source: <chart name>/templates/x.yaml`.
52	var helmSourceLine = regexp.MustCompile(`^# Source: (\S+)`)
53	
54	// renderScope is where a renderer runs. A binary runs in the target and sees
55	// the whole host. A container sees only mount, read-only at /scan, and works in
56	// the target inside it: mount is the target itself, or the git repository
57	// holding it, so an overlay or a chart can reach a sibling of the target as it
58	// does on the host (DEVDESK-742).
59	type renderScope struct {
60		target string
61		mount  string
62		// rel is the target relative to mount, with forward slashes; "" when the
63		// target is what is mounted.
64		rel string
65	}
66	
67	// targetOnly mounts the target and nothing else.
68	func targetOnly(target string) renderScope { return renderScope{target: target, mount: target} }
69	
70	// workdir is the target inside the container.
71	func (s renderScope) workdir() string { return path.Join(containerScanPath, s.rel) }
72	
73	// userHomeDir is the home directory the mount guard keeps out of reach. Tests
74	// swap it.
75	var userHomeDir = os.UserHomeDir
76	
77	// resolveRenderScope asks git, in the target, for the repository holding it.
78	// Without an answer (no git, not a repository), or when the repository's
79	// configuration moves its work tree elsewhere (core.worktree, which a cloned
80	// .git file can bring along), the target alone is mounted.
81	func resolveRenderScope(ctx context.Context, target string) renderScope {
82		git := func(args ...string) ([]byte, error) {
83			return runner.Run(ctx, toolCmd{Name: "git", Args: args, Dir: target, Env: gitEnviron(os.Environ())}, nil)
84		}
85		out, err := git("rev-parse", "--show-toplevel")
86		if err != nil {
87			log.Printf("[scan/k8s] %s: no git repository to mount, the renderers see the target only: %v", target, err)
88			return targetOnly(target)
89		}
90		worktree, err := git("config", "--get", "core.worktree")
91		var exitErr *exitError
92		unset := errors.As(err, &exitErr) && exitErr.Code == 1 && len(bytes.TrimSpace(worktree)) == 0
93		if !unset {
94			log.Printf("[scan/k8s] %s: core.worktree is set or unreadable (%q, %v), the renderers see the target only",
95				target, strings.TrimSpace(string(worktree)), err)
96			return targetOnly(target)
97		}
98		scope, ok := widerScope(target, strings.TrimSpace(string(out)))
99		if !ok {
100			return targetOnly(target)
101		}
102		log.Printf("[scan/k8s] renderers in a container mount %s, the repository holding %s", scope.mount, target)
103		return scope
104	}
105	
106	// gitEnviron is env without the variables that point git at another
107	// repository, work tree or configuration: the mount is decided by the target
108	// alone. GIT_CEILING_DIRECTORIES stays: it can only stop git's search for the
109	// repository earlier, and dropping it would widen what the user limited.
110	func gitEnviron(env []string) []string {
111		out := make([]string, 0, len(env))
112		for _, kv := range env {
113			name, _, _ := strings.Cut(kv, "=")
114			switch {
115			case name == "GIT_DIR", name == "GIT_WORK_TREE", name == "GIT_COMMON_DIR",
116				strings.HasPrefix(name, "GIT_CONFIG"):
117				continue
118			}
119			out = append(out, kv)
120		}
121		return out
122	}
123	
124	// widerScope mounts top, the repository git named, when it is safe to: top is
125	// a strict ancestor of the target once symlinks are resolved, neither the
126	// filesystem root nor the home directory nor anything above it, and it holds
127	// the repository's .git itself (gitDirIsHere). Anything else, an unknown home
128	// included, keeps the target alone.
129	func widerScope(target, top string) (renderScope, bool) {
130		if top == "" || !filepath.IsAbs(top) {
131			return renderScope{}, false
132		}
133		root, err := filepath.EvalSymlinks(top)
134		if err != nil {
135			return renderScope{}, false
136		}
137		real, err := filepath.EvalSymlinks(target)
138		if err != nil {
139			return renderScope{}, false
140		}
141		rel, err := filepath.Rel(root, real)
142		if err != nil || rel == "." || rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
143			return renderScope{}, false
144		}
145		if filepath.Dir(root) == root {
146			return renderScope{}, false
147		}
148		home, err := userHomeDir()
149		if err != nil || home == "" {
150			return renderScope{}, false
151		}
152		if h, err := filepath.EvalSymlinks(home); err == nil {
153			home = h
154		}
155		if r, err := filepath.Rel(root, filepath.Clean(home)); err == nil &&
156			(r == "." || (r != ".." && !strings.HasPrefix(r, ".."+string(filepath.Separator)))) {
157			return renderScope{}, false
158		}
159		if !gitDirIsHere(root) {
160			return renderScope{}, false
161		}
162		return renderScope{target: target, mount: root, rel: filepath.ToSlash(rel)}, true
163	}
164	
165	// maxGitFile bounds what is read of a .git file or a worktree's gitdir file:
166	// one line, a path.
167	const maxGitFile = 4096
168	
169	// gitDirIsHere reports whether root holds its repository's .git: a directory,
170	// or the file of a linked worktree ("gitdir: <dir>") whose git directory names
171	// root's .git back in its own gitdir file. A symlink, a file that says
172	// anything else, or a git directory that does not point back is refused: git
173	// was then told where the work tree is, rather than finding it.
174	func gitDirIsHere(root string) bool {
175		dotGit := filepath.Join(root, ".git")
176		info, err := os.Lstat(dotGit)
177		if err != nil {
178			return false
179		}
180		if info.IsDir() {
181			return true
182		}
183		if !info.Mode().IsRegular() {
184			return false
185		}
186		line, ok := readGitFile(dotGit)
187		gitDir, found := strings.CutPrefix(line, "gitdir: ")
188		if !ok || !found {
189			return false
190		}
191		if !filepath.IsAbs(gitDir) {
192			gitDir = filepath.Join(root, gitDir)
193		}
194		back, ok := readGitFile(filepath.Join(gitDir, "gitdir"))
195		if !ok {
196			return false
197		}
198		if !filepath.IsAbs(back) {
199			back = filepath.Join(gitDir, back)
200		}
201		a, errA := filepath.EvalSymlinks(back)
202		b, errB := filepath.EvalSymlinks(dotGit)
203		return errA == nil && errB == nil && a == b
204	}
205	
206	// readGitFile reads the one line of a small regular file.
207	func readGitFile(p string) (string, bool) {
208		info, err := os.Lstat(p)
209		if err != nil || !info.Mode().IsRegular() || info.Size() > maxGitFile {
210			return "", false
211		}
212		data, err := os.ReadFile(p) //nolint:gosec // a .git file of the repository being scanned
213		if err != nil {
214			return "", false
215		}
216		return strings.TrimSpace(string(data)), true
217	}
218	
219	// renderer runs one tool in the repository, the way every other tool runs:
220	// in the target for a binary; for an image, with the scope's mount read-only
221	// at /scan and the target inside it as the working directory.
222	func renderer(scope renderScope, tool ToolSpec, defaultImage, binary string, args ...string) toolCmd {
223		// helm gets them on lint and on template alike: only the flags the two
224		// share (--values, --set…) make sense there.
225		args = afterSubcommand(args, tool.Args)
226		if tool.Source != ToolSourceContainer {
227			name := tool.Binary
228			if name == "" {
229				name = binary
230			}
231			return toolCmd{Name: name, Args: args, Dir: scope.target}
232		}
233		return containerRun{
234			Flags: []string{"-v", scope.mount + ":" + containerScanPath + ":ro", "-w", scope.workdir()},
235			Image: orDefault(tool.Image, defaultImage),
236			Argv:  args,
237		}.cmd()
238	}
239	
240	func orDefault(v, def string) string {
241		if v == "" {
242			return def
243		}
244		return v
245	}
246	
247	func helmArgs(scope renderScope, chart string, tool ToolSpec, sub string) toolCmd {
248		return renderer(scope, tool, DefaultHelmImage, "helm", sub, chart)
249	}
250	
251	func kustomizeArgs(scope renderScope, dir string, tool ToolSpec) toolCmd {
252		return renderer(scope, tool, DefaultKustomizeImage, "kustomize", "build", dir)
253	}
254	
255	// kubeconformStdinArgs validates what arrives on stdin. A container gets -i
256	// and no repository mount: it reads nothing but its input and its cache.
257	func kubeconformStdinArgs(rendered []byte, tool ToolSpec, opts KubeconformOptions) toolCmd {
258		flags := kubeconformFlags(tool, opts)
259		if tool.Source != ToolSourceContainer {
260			return toolCmd{Name: kubeconformBinary(tool), Args: append(flags, "-"), Stdin: rendered}
261		}
262		engineArgs := []string{"-i"}
263		if opts.CacheDir != "" {
264			engineArgs = append(engineArgs, "-v", opts.CacheDir+":"+kubeconformCacheMount)
265		}
266		return containerRun{
267			Flags: engineArgs, Image: kubeconformImage(tool.Image), Argv: append(flags, "-"), Stdin: rendered,
268		}.cmd()
269	}
270	
271	// k8sValidation is one schema stage over one repository: the tools it has,
272	// what it validates against, and the report it fills in.
273	type k8sValidation struct {
274		target string
275		// scope is where helm and kustomize run, resolved once per stage.
276		scope       renderScope
277		kubeconform ToolSpec
278		opts        KubeconformOptions
279		report      *KubeconformReport
280	}
281	
282	// available reports whether an optional renderer was resolved at all.
283	func available(tool ToolSpec) bool {
284		return tool.Source != ToolSourceNone && tool.Source != ""
285	}
286	
287	// renderCharts lints, renders and validates each chart. Without helm, every
288	// chart is reported as not rendered.
289	func (v *k8sValidation) renderCharts(ctx context.Context, charts []string) error {
290		tool := v.opts.Helm
291		for _, chart := range charts {
292			if !available(tool) {
293				v.report.Unrendered = append(v.report.Unrendered, chart)
294				continue
295			}
296			lint := helmLint(ctx, v.scope, chart, tool)
297			v.report.Findings = append(v.report.Findings, lint...)
298	
299			cmd := helmArgs(v.scope, chart, tool, "template")
300			log.Printf("Running: %s", cmd)
301			rendered, err := runner.Run(ctx, cmd, nil)
302			if err != nil {
303				if ctx.Err() != nil {
304					return ctx.Err()
305				}
306				// helm lint renders the chart too, so a chart that does not
307				// render has usually been reported by it already, with more to
308				// say. The render failure is the fallback, not a second copy.
309				if !hasError(lint) {
310					v.report.Findings = append(v.report.Findings,
311						renderFailure(SourceHelm, "helm", path.Join(chart, "Chart.yaml"), "Chart does not render", tool.Source, err))
312				}
313				continue
314			}
315			origins := helmOrigins(rendered, chart)
316			err = v.validateRendered(ctx, rendered, "helm", func(kind, name string) string {
317				if file, ok := origins[kind+"/"+name]; ok {
318					return file
319				}
320				return chart
321			})
322			if err != nil {
323				return fmt.Errorf("chart %s: %w", chart, err)
324			}
325		}
326		return nil
327	}
328	
329	// renderKustomizations builds and validates each overlay. Without kustomize,
330	// every overlay is reported as not rendered.
331	func (v *k8sValidation) renderKustomizations(ctx context.Context, dirs []string) error {
332		tool := v.opts.Kustomize
333		for _, dir := range dirs {
334			if !available(tool) {
335				v.report.Unrendered = append(v.report.Unrendered, dir)
336				continue
337			}
338			file := path.Join(dir, k8s.KustomizationFile(filepath.Join(v.target, filepath.FromSlash(dir))))
339			cmd := kustomizeArgs(v.scope, dir, tool)
340			log.Printf("Running: %s", cmd)
341			rendered, err := runner.Run(ctx, cmd, nil)
342			if err != nil {
343				if ctx.Err() != nil {
344					return ctx.Err()
345				}
346				v.report.Findings = append(v.report.Findings,
347					renderFailure(SourceKustomize, "kustomize", file, "Overlay does not build", tool.Source, err))
348				continue
349			}
350			// kustomize adds no origin to what it emits unless the kustomization
351			// asks for it, and DevDesk does not write into the file to ask. The
352			// overlay is what was built, so it is what a finding points at.
353			err = v.validateRendered(ctx, rendered, "kustomize", func(string, string) string { return file })
354			if err != nil {
355				return fmt.Errorf("overlay %s: %w", dir, err)
356			}
357		}
358		return nil
359	}
360	
361	// validateRendered runs kubeconform over rendered YAML and points each
362	// finding back at the file it came from. A rendered line is not a line of
363	// any file in the repository, so these findings carry none.
364	func (v *k8sValidation) validateRendered(ctx context.Context, rendered []byte, dialect string, origin func(kind, name string) string) error {
365		if len(bytes.TrimSpace(rendered)) == 0 {
366			return nil
367		}
368		cmd := kubeconformStdinArgs(rendered, v.kubeconform, v.opts)
369		log.Printf("Running: %s", cmd)
370		out, err := runner.Run(ctx, cmd, nil)
371		if err := kubeconformFailure(out, err); err != nil {
372			return err
373		}
374		noFile := func(string) ([]byte, error) { return nil, errors.New("rendered, not a file") }
375		findings, skipped, err := parseKubeconformOutput(out, v.opts.KubernetesVersion, noFile, origin)
376		if err != nil {
377			return err
378		}
379		v.report.SkippedCustom += skipped
380		for i := range findings {
381			findings[i].IaCType = dialect
382		}
383		v.report.Findings = append(v.report.Findings, findings...)
384		return nil
385	}
386	
387	// helmLint runs helm lint and returns its warnings and errors. helm exits 1
388	// when a chart fails; its messages are still the answer. A run that printed
389	// nothing parseable is logged and yields nothing — the render that follows
390	// will say whether the chart is usable.
391	func helmLint(ctx context.Context, scope renderScope, chart string, tool ToolSpec) []Finding {
392		cmd := helmArgs(scope, chart, tool, "lint")
393		log.Printf("Running: %s", cmd)
394		out, err := runner.Run(ctx, cmd, nil)
395		findings, recognised := parseHelmLint(out, chart, scope)
396		if err != nil && !recognised {
397			log.Printf("ERROR [scan/helm] lint %s: %v", chart, err)
398		}
399		return findings
400	}
401	
402	// parseHelmLint turns helm lint's text into findings. The second result says
403	// the output was helm lint's at all.
404	//
405	// A message's path is usually relative to the chart ("templates/cm.yaml"),
406	// but not always: the missing-dependency warning names the chart directory
407	// absolutely — "/scan/charts/broken" in a container, measured on helm 4.3.0.
408	// Both are brought back to a path relative to the target.
409	func parseHelmLint(out []byte, chart string, scope renderScope) ([]Finding, bool) {
410		file := func(p string) string { return helmLintPath(p, chart, scope) }
411		var findings []Finding
412		recognised := false
413		sc := bufio.NewScanner(bytes.NewReader(out))
414		for sc.Scan() {
415			line := strings.TrimSpace(sc.Text())
416			switch {
417			case strings.HasPrefix(line, "==> Linting"):
418				recognised = true
419			case strings.HasPrefix(line, "Error "):
420				// Printed instead of the messages when the chart could not be
421				// loaded at all.
422				recognised = true
423				findings = append(findings, helmLintFinding(chart, SeverityHigh, strings.TrimPrefix(line, "Error ")))
424			default:
425				m := helmLintLine.FindStringSubmatch(line)
426				if m == nil {
427					continue
428				}
429				recognised = true
430				switch m[1] {
431				case "ERROR":
432					findings = append(findings, helmLintFinding(file(m[2]), SeverityHigh, m[3]))
433				case "WARNING":
434					findings = append(findings, helmLintFinding(file(m[2]), SeverityLow, m[3]))
435				}
436			}
437		}
438		return findings, recognised
439	}
440	
441	// helmLintPath resolves a path helm lint printed to one relative to the
442	// target. In a container the target is the scope's working directory, which is
443	// /scan itself unless the git repository around the target is mounted.
444	func helmLintPath(p, chart string, scope renderScope) string {
445		p = strings.TrimSuffix(p, "/")
446		switch {
447		case p == containerScanPath || strings.HasPrefix(p, containerScanPath+"/"):
448			if rel, err := filepath.Rel(filepath.FromSlash(scope.workdir()), filepath.FromSlash(p)); err == nil {
449				return filepath.ToSlash(rel)
450			}
451			return p
452		case filepath.IsAbs(p):
453			if rel, err := filepath.Rel(scope.target, p); err == nil && !strings.HasPrefix(rel, "..") {
454				return filepath.ToSlash(rel)
455			}
456			return filepath.ToSlash(p)
457		default:
458			return path.Join(chart, p)
459		}
460	}
461	
462	func helmLintFinding(file string, severity SeverityLevel, msg string) Finding {
463		return Finding{
464			ID:          HelmLintID,
465			Title:       msg,
466			Description: "helm lint reported this about the chart.",
467			Message:     msg,
468			Severity:    severity,
469			Source:      SourceHelm,
470			File:        file,
471			IaCType:     "helm",
472		}
473	}
474	
475	func hasError(findings []Finding) bool {
476		for _, f := range findings {
477			if f.Severity == SeverityHigh {
478				return true
479			}
480		}
481		return false
482	}
483	
484	// renderFailure is a chart or an overlay that could not be rendered: nothing
485	// in it was validated, and `helm install` or `kubectl apply -k` would fail the
486	// same way.
487	func renderFailure(source, dialect, file, title string, from ToolSource, err error) Finding {
488		detail := err.Error()
489		var exitErr *exitError
490		if errors.As(err, &exitErr) && exitErr.Stderr != "" {
491			detail = strings.TrimSpace(exitErr.Stderr)
492		}
493		first, _, _ := strings.Cut(detail, "\n")
494		return Finding{
495			ID:          K8sRenderID,
496			Title:       title + ": " + first,
497			Description: "The directory could not be rendered, so none of its resources were validated.",
498			Message:     detail,
499			Resolution:  renderResolution(source, from, detail),
500			Severity:    SeverityHigh,
501			Source:      source,
502			File:        file,
503			IaCType:     dialect,
504		}
505	}
506	
507	// How to fix a chart or an overlay that does not render, in the renderer's own
508	// terms.
509	const (
510		helmRenderResolution = "Render it locally with helm template and fix what it reports; " +
511			"a chart's dependencies must be vendored in charts/ or fetched with helm dependency build."
512		kustomizeRenderResolution = "Build it locally with kustomize build (or kubectl kustomize) and fix what it reports."
513		// kustomize's load restrictor (LoadRestrictionsRootOnly, its default)
514		// refuses a file outside the kustomization's directory, with this message.
515		// The flag is not reserved (ToolKustomize.ReservedArgs) and lands after
516		// `build` (afterSubcommand), where kustomize accepts it.
517		loadRestrictorResolution = "kustomize refuses by default a file outside the overlay directory " +
518			"(same as kubectl apply -k). Reference a directory with its own kustomization instead, " +
519			"or, if your deployment tool allows it, set " +
520			"scan.tools.kustomize.args: [--load-restrictor=LoadRestrictionsNone]."
521	)
522	
523	// mountResolution is added for a kustomize image that could not find a path:
524	// the container sees only what DevDesk mounts (renderScope), and DevDesk does
525	// not walk the repository to tell a hidden reference from a broken one.
526	// ToolConfig's `source` key takes auto, binary or image.
527	const mountResolution = "If this reference points outside the directory DevDesk mounts into the container " +
528		"(the scanned directory, or its git repository when it has one), scan the enclosing directory, " +
529		"or set scan.tools.kustomize.source: binary (the binary sees the whole file system)."
530	
531	// renderResolution picks the advice for a render failure from the renderer,
532	// where it ran and what it printed.
533	func renderResolution(source string, from ToolSource, detail string) string {
534		if source != SourceKustomize {
535			return helmRenderResolution
536		}
537		advice := kustomizeRenderResolution
538		if strings.Contains(detail, "security; file") && strings.Contains(detail, "is not in or below") {
539			advice = loadRestrictorResolution
540		}
541		if from == ToolSourceContainer &&
542			(strings.Contains(detail, "evalsymlink failure") || strings.Contains(detail, "no such file or directory")) {
543			advice += " " + mountResolution
544		}
545		return advice
546	}
547	
548	// helmOrigins maps each rendered resource, by kind and name, to the template
549	// it came from, relative to the repository. helm names the template under the
550	// chart's own name, which need not be its directory's.
551	func helmOrigins(rendered []byte, chart string) map[string]string {
552		origins := map[string]string{}
553		for _, doc := range splitYAMLDocuments(rendered) {
554			var source string
555			for _, line := range strings.Split(doc, "\n") {
556				if m := helmSourceLine.FindStringSubmatch(line); m != nil {
557					source = m[1]
558					break
559				}
560			}
561			if source == "" {
562				continue
563			}
564			var meta struct {
565				Kind     string `yaml:"kind"`
566				Metadata struct {
567					Name string `yaml:"name"`
568				} `yaml:"metadata"`
569			}
570			if yaml.Unmarshal([]byte(doc), &meta) != nil || meta.Kind == "" {
571				continue
572			}
573			key := meta.Kind + "/" + meta.Metadata.Name
574			if _, seen := origins[key]; seen {
575				continue
576			}
577			_, rest, _ := strings.Cut(source, "/")
578			origins[key] = path.Join(chart, rest)
579		}
580		return origins
581	}
582	
583	// splitYAMLDocuments splits a multi-document stream on its `---` separators.
584	func splitYAMLDocuments(stream []byte) []string {
585		var docs []string
586		var cur strings.Builder
587		r := bufio.NewReader(bytes.NewReader(stream))
588		for {
589			line, err := r.ReadString('\n')
590			if strings.TrimRight(line, "\r\n") == "---" {
591				docs = append(docs, cur.String())
592				cur.Reset()
593			} else {
594				cur.WriteString(line)
595			}
596			if errors.Is(err, io.EOF) || err != nil {
597				break
598			}
599		}
600		return append(docs, cur.String())
601	}
