255	// kubeconformStdinArgs validates what arrives on stdin. A container gets -i
256	// and no repository mount: it reads nothing but its input and its cache.
257	func kubeconformStdinArgs(rendered []byte, tool ToolSpec, opts KubeconformOptions) toolCmd {
258		flags := kubeconformFlags(tool, opts)
259		if tool.Source != ToolSourceContainer {
260			return toolCmd{Name: kubeconformBinary(tool), Args: append(flags, "-"), Stdin: rendered}
261		}
262		engineArgs := []string{"-i"}
263		if opts.CacheDir != "" {
264			engineArgs = append(engineArgs, "-v", opts.CacheDir+":"+kubeconformCacheMount)
265		}
266		return containerRun{
267			Flags: engineArgs, Image: kubeconformImage(tool.Image), Argv: append(flags, "-"), Stdin: rendered,
268		}.cmd()
269	}
