484	// renderFailure is a chart or an overlay that could not be rendered: nothing
485	// in it was validated, and `helm install` or `kubectl apply -k` would fail the
486	// same way.
487	func renderFailure(source, dialect, file, title string, from ToolSource, err error) Finding {
488		detail := err.Error()
489		var exitErr *exitError
490		if errors.As(err, &exitErr) && exitErr.Stderr != "" {
491			detail = strings.TrimSpace(exitErr.Stderr)
492		}
493		first, _, _ := strings.Cut(detail, "\n")
494		return Finding{
495			ID:          K8sRenderID,
496			Title:       title + ": " + first,
497			Description: "The directory could not be rendered, so none of its resources were validated.",
498			Message:     detail,
499			Resolution:  renderResolution(source, from, detail),
500			Severity:    SeverityHigh,
501			Source:      source,
502			File:        file,
503			IaCType:     dialect,
504		}
505	}
