507	// How to fix a chart or an overlay that does not render, in the renderer's own
508	// terms.
509	const (
510		helmRenderResolution = "Render it locally with helm template and fix what it reports; " +
511			"a chart's dependencies must be vendored in charts/ or fetched with helm dependency build."
512		kustomizeRenderResolution = "Build it locally with kustomize build (or kubectl kustomize) and fix what it reports."
513		// kustomize's load restrictor (LoadRestrictionsRootOnly, its default)
514		// refuses a file outside the kustomization's directory, with this message.
515		// The flag is not reserved (ToolKustomize.ReservedArgs) and lands after
516		// `build` (afterSubcommand), where kustomize accepts it.
517		loadRestrictorResolution = "kustomize refuses by default a file outside the overlay directory " +
518			"(same as kubectl apply -k). Reference a directory with its own kustomization instead, " +
519			"or, if your deployment tool allows it, set " +
520			"scan.tools.kustomize.args: [--load-restrictor=LoadRestrictionsNone]."
521	)
522	
523	// mountResolution is added for a kustomize image that could not find a path:
524	// the container sees only what DevDesk mounts (renderScope), and DevDesk does
525	// not walk the repository to tell a hidden reference from a broken one.
526	// ToolConfig's `source` key takes auto, binary or image.
527	const mountResolution = "If this reference points outside the directory DevDesk mounts into the container " +
528		"(the scanned directory, or its git repository when it has one), scan the enclosing directory, " +
529		"or set scan.tools.kustomize.source: binary (the binary sees the whole file system)."
530	
531	// renderResolution picks the advice for a render failure from the renderer,
532	// where it ran and what it printed.
533	func renderResolution(source string, from ToolSource, detail string) string {
534		if source != SourceKustomize {
535			return helmRenderResolution
536		}
537		advice := kustomizeRenderResolution
538		if strings.Contains(detail, "security; file") && strings.Contains(detail, "is not in or below") {
539			advice = loadRestrictorResolution
540		}
541		if from == ToolSourceContainer &&
542			(strings.Contains(detail, "evalsymlink failure") || strings.Contains(detail, "no such file or directory")) {
543			advice += " " + mountResolution
544		}
545		return advice
546	}
547	
548	// helmOrigins maps each rendered resource, by kind and name, to the template
549	// it came from, relative to the repository. helm names the template under the
550	// chart's own name, which need not be its directory's.
551	func helmOrigins(rendered []byte, chart string) map[string]string {
552		origins := map[string]string{}
553		for _, doc := range splitYAMLDocuments(rendered) {
554			var source string
555			for _, line := range strings.Split(doc, "\n") {
556				if m := helmSourceLine.FindStringSubmatch(line); m != nil {
557					source = m[1]
558					break
559				}
560			}
561			if source == "" {
562				continue
563			}
564			var meta struct {
565				Kind     string `yaml:"kind"`
566				Metadata struct {
567					Name string `yaml:"name"`
568				} `yaml:"metadata"`
569			}
570			if yaml.Unmarshal([]byte(doc), &meta) != nil || meta.Kind == "" {
571				continue
572			}
573			key := meta.Kind + "/" + meta.Metadata.Name
574			if _, seen := origins[key]; seen {
575				continue
576			}
577			_, rest, _ := strings.Cut(source, "/")
578			origins[key] = path.Join(chart, rest)
579		}
580		return origins
581	}
582	
583	// splitYAMLDocuments splits a multi-document stream on its `---` separators.
584	func splitYAMLDocuments(stream []byte) []string {
585		var docs []string
586		var cur strings.Builder
587		r := bufio.NewReader(bytes.NewReader(stream))
588		for {
589			line, err := r.ReadString('\n')
590			if strings.TrimRight(line, "\r\n") == "---" {
591				docs = append(docs, cur.String())
592				cur.Reset()
593			} else {
594				cur.WriteString(line)
595			}
596			if errors.Is(err, io.EOF) || err != nil {
597				break
598			}
599		}
600		return append(docs, cur.String())
601	}
