167	// kubeconformFailure tells a run that found problems from one that failed.
168	// kubeconform exits 1 for both; what separates them is whether it wrote its
169	// JSON report.
170	func kubeconformFailure(out []byte, err error) error {
171		if err == nil {
172			return nil
173		}
174		var exitErr *exitError
175		if errors.As(err, &exitErr) && exitErr.Code == 1 && looksLikeJSON(out) {
176			return nil
177		}
178		return err
179	}
180	
181	func looksLikeJSON(out []byte) bool {
182		for _, b := range out {
183			switch b {
184			case ' ', '\n', '\r', '\t':
185				continue
186			case '{':
187				return true
188			default:
189				return false
190			}
191		}
192		return false
193	}
