195	// fileReader reads a file relative to root, for locating a finding's line.
196	func fileReader(root string) func(string) ([]byte, error) {
197		return func(name string) ([]byte, error) {
198			return os.ReadFile(filepath.Join(root, filepath.FromSlash(name))) //nolint:gosec // a manifest of the repository being scanned
199		}
200	}
