225	// KubeconformCacheDir is where schemas are cached: beside the scan caches,
226	// under ~/.devdesk/cache. Empty when there is no home directory, which only
227	// costs the cache.
228	func KubeconformCacheDir() string {
229		home, err := os.UserHomeDir()
230		if err != nil {
231			return ""
232		}
233		return filepath.Join(home, ".devdesk", "cache", "kubeconform")
