236	// kubernetesVersionPattern is what kubeconform accepts for -kubernetes-version:
237	// its own regexp, from pkg/config/config.go.
238	var kubernetesVersionPattern = regexp.MustCompile(`^(master|\d+\.\d+\.\d+)$`)
239	
240	// ValidateKubernetesVersion refuses what kubeconform would refuse, so the
241	// configuration view says it at the field rather than every scan failing on
242	// it. Empty is accepted: it means the default release.
243	func ValidateKubernetesVersion(v string) error {
244		if v == "" || kubernetesVersionPattern.MatchString(v) {
245			return nil
246		}
247		return fmt.Errorf("%q is not a version: use a full x.y.z such as %s, or master", v, config.DefaultKubernetesVersion)
248	}
