250	// kubeconformOptions is what this scanner validates against, and the
251	// renderers it has — an unavailable one is handed over unresolved.
252	func (s *Scanner) kubeconformOptions() KubeconformOptions {
253		opts := KubeconformOptions{KubernetesVersion: s.options.Tools.Kubeconform.KubernetesVersion, CacheDir: KubeconformCacheDir()}
254		// A renderer serves only when it is ticked: installed and unticked, it is
255		// not used (§3.86), and its charts or overlays are reported as not rendered.
256		if s.runs(CategoryIDMisconfig, ToolHelm, TargetDirectory) {
257			opts.Helm = s.spec(ToolHelm)
258		}
259		if s.runs(CategoryIDMisconfig, ToolKustomize, TargetDirectory) {
260			opts.Kustomize = s.spec(ToolKustomize)
261		}
262		return opts
263	}
