265	// runKubeconformStage is the schema stage of Scan, shaped like the others:
266	// progress, then findings or a stage error under the result's lock.
267	func (s *Scanner) runKubeconformStage(ctx context.Context, target string, result *Result, mu *sync.Mutex, notify func(ProgressUpdate)) {
268		const stage, label = "k8s-schema", "Kubernetes schema"
269		notify(ProgressUpdate{Stage: stage, Label: label, Status: StageRunning})
270		progressFn := func(detail string) {
271			notify(ProgressUpdate{Stage: stage, Label: label, Status: StageRunning, Detail: detail})
272		}
273		report, err := RunKubeconform(ctx, target, s.spec(ToolKubeconform), s.kubeconformOptions(), progressFn)
274	
275		mu.Lock()
276		defer mu.Unlock()
277		if err != nil {
278			recordStageError(result, "kubeconform", err)
279			notify(ProgressUpdate{Stage: stage, Label: label, Status: StageError, Detail: err.Error()})
280			return
281		}
282		if report.SkippedCustom > 0 {
283			log.Printf("[scan/kubeconform] %s: %d custom resources not validated (their schema is in a CRD)", target, report.SkippedCustom)
284		}
285		if len(report.Unrendered) > 0 {
286			log.Printf("[scan/kubeconform] %s: not rendered, so not validated: %s", target, strings.Join(report.Unrendered, ", "))
287		}
288		result.K8sUnrendered = report.Unrendered
289		result.Findings = append(result.Findings, report.Findings...)
290		// Schema validation is the second half of the Misconfiguration category, so
291		// a run of it makes the verdict known on its own: a repository scanned with
292		// Trivy's rules switched off but kubeconform on has been looked at, and a
293		// "-" there would say otherwise. What the stage could not render is carried
294		// in K8sUnrendered and comes back out as the column's "?".
295		result.MisconfigScanned = true
296		notify(ProgressUpdate{Stage: stage, Label: label, Status: StageDone})
297	}
