1	package security
2	
3	import (
4		"path/filepath"
5		"strconv"
6		"strings"
7		"unicode"
8	
9		"github.com/anthnel/devdesk/internal/remediation"
10		"github.com/anthnel/devdesk/internal/scan"
11		"github.com/anthnel/devdesk/internal/ui/shortcut"
12	)
13	
14	// fixState is the state behind the Fix line of a finding detail (DEVDESK-751).
15	type fixState int
16	
17	const (
18		fixManual fixState = iota
19		fixBuiltIn
20		fixBuiltInDeclined
21		fixNoFixPublished
22		fixCannotFixHere
23		fixNoGuidance
24	)
25	
26	// The closed vocabulary of the Fix line (AC1). Only labelBuiltInUnavailable
27	// carries a reason, which Label appends after a colon.
28	const (
29		labelBuiltInAvailable   = "Built-in fix available"
30		labelBuiltInUnavailable = "Built-in fix unavailable"
31		labelManual             = "Manual"
32		labelNoFixPublished     = "No fix published"
33		labelCannotFixHere      = "Cannot fix here"
34		labelNoGuidance         = "No guidance available"
35	)
36	
37	// Reasons a finding's file cannot be opened from the detail (Rule 130).
38	const (
39		reasonFileOutsideTarget = "This file is outside the scanned directory"
40		reasonNoFile            = "This finding names no file"
41		// reasonFileLinkOutsideTarget is the answer of enter, which follows links:
42		// the header cannot know it (it reads no disk).
43		reasonFileLinkOutsideTarget = "This file is reached through a link that leaves the scanned directory"
44	)
45	
46	// fixStatus is the Fix line of a finding detail, in words: a colour or a key
47	// name alone would not say it (Rule 134), so the status never names a key.
48	type fixStatus struct {
49		State   fixState
50		Reason  string // why the built-in fix is unavailable or cannot run here
51		Effect  string // what the fix does: the catalog rule's title, or "Fixed in <v>"
52		Warning string // remediation.Rule.Warning, or ""
53	}
54	
55	// Label is the closed-vocabulary text of the status.
56	func (s fixStatus) Label() string {
57		switch s.State {
58		case fixBuiltIn:
59			return labelBuiltInAvailable
60		case fixBuiltInDeclined:
61			return labelBuiltInUnavailable + ": " + s.Reason
62		case fixManual:
63			return labelManual
64		case fixNoFixPublished:
65			return labelNoFixPublished
66		case fixCannotFixHere:
67			return labelCannotFixHere
68		}
69		return labelNoGuidance
70	}
71	
72	// fixStatusOf says whether f can be fixed and why not. For a misconfiguration
73	// it reads misconfigFixAvailability, the computation behind the shortcut column,
74	// so the detail and the header agree (Rule 130).
75	func fixStatusOf(f scan.Finding, onDisk bool) fixStatus {
76		switch scan.Categorize(f) {
77		case scan.CategoryMisconfiguration:
78			return misconfigFixStatus(f, onDisk)
79		case scan.CategoryVulnerability:
80			if f.FixedIn != "" {
81				return fixStatus{State: fixManual, Effect: "Fixed in " + f.FixedIn}
82			}
83			return fixStatus{State: fixNoFixPublished}
84		}
85		return guidanceStatus(f)
86	}
87	
88	// misconfigFixStatus is the status of a misconfiguration, in the order of
89	// misconfigFixAvailability: an image first, then the catalog, then the guidance
90	// a finding the catalog does not know can still carry.
91	func misconfigFixStatus(f scan.Finding, onDisk bool) fixStatus {
92		rule, a := misconfigFixAvailability(f, onDisk)
93		switch {
94		case !onDisk:
95			return fixStatus{State: fixCannotFixHere, Reason: a.Reason}
96		case a.Enabled():
97			return fixStatus{State: fixBuiltIn, Effect: rule.Title, Warning: rule.Warning}
98		case rule.AVDID != "":
99			return fixStatus{State: fixBuiltInDeclined, Reason: a.Reason}
100		}
101		return guidanceStatus(f)
102	}
103	
104	// guidanceStatus is Manual when the finding tells how to fix it by hand, and
105	// No guidance available when it does not.
106	func guidanceStatus(f scan.Finding) fixStatus {
107		if hasGuidance(f) {
108			return fixStatus{State: fixManual}
109		}
110		return fixStatus{State: fixNoGuidance}
111	}
112	
113	// hasGuidance says whether f carries any instruction: a Resolution, a
114	// FixCommand or a remediation.MissingFor text.
115	func hasGuidance(f scan.Finding) bool {
116		if f.Resolution != "" || f.FixCommand != "" {
117			return true
118		}
119		_, ok := remediation.MissingFor(f)
120		return ok
121	}
122	
123	// shellMeta are the characters that make a shell read more than words in a
124	// command: separators, expansions, redirections, quoting, globbing, comments.
125	const shellMeta = ";|&$`<>()\\'\"{}*?!#"
126	
127	// runCommand is the text under Run and the text Y copies: the FixCommand trimmed,
128	// when fixAction calls it a command and it is plain words. One computation, two
129	// readers.
130	//
131	// The command is pasted into a shell, and its names and versions come from a
132	// scan, so anything but words is refused (DEVDESK-751): a line break, a control
133	// character (an escape sequence, a tab, a carriage return), a blank other than a
134	// single space, a character that has no visible form (a zero-width or
135	// right-to-left mark) or a shell metacharacter. A refused command is not lost:
136	// fixSteps shows its text under Do.
137	func runCommand(f scan.Finding) (string, bool) {
138		label, text := fixAction(f)
139		cmd := strings.TrimSpace(text)
140		if label != "Run" || cmd == "" || !plainWords(cmd) {
141			return "", false
142		}
143		return cmd, true
144	}
145	
146	// plainWords reports whether cmd is made of visible characters and single
147	// spaces, with no shell metacharacter.
148	func plainWords(cmd string) bool {
149		for _, r := range cmd {
150			switch {
151			case r == ' ':
152			case unicode.IsControl(r), !unicode.IsPrint(r), strings.ContainsRune(shellMeta, r):
153				return false
154			}
155		}
156		return true
157	}
158	
159	// fixSteps are the numbered steps under Do: what a rule the catalog cannot fix
160	// is missing, and a FixCommand that is not offered under Run: a sentence rather
161	// than a command, or a command runCommand refuses.
162	func fixSteps(f scan.Finding) []string {
163		var steps []string
164		if _, inCatalog := remediation.FixFor(f); !inCatalog {
165			if text, ok := remediation.MissingFor(f); ok {
166				steps = append(steps, text)
167			}
168		}
169		if _, offered := runCommand(f); !offered {
170			if _, text := fixAction(f); strings.TrimSpace(text) != "" {
171				steps = append(steps, text)
172			}
173		}
174		return steps
175	}
176	
177	// fact is one labelled value of the Where section.
178	type fact struct{ Label, Value string }
179	
180	// whereFacts are the facts under Where, in order: File, Package, Job, Script,
181	// Match. A path is shown the way shortPaths shows it, with its line.
182	func whereFacts(f scan.Finding, target string) []fact {
183		var facts []fact
184		add := func(label, value string) {
185			if value != "" {
186				facts = append(facts, fact{label, value})
187			}
188		}
189		file := shortPaths(f.File, target)
190		if file != "" && f.Line > 0 {
191			file += ":" + strconv.Itoa(f.Line)
192		}
193		add("File", file)
194		add("Package", packageFact(f))
195		add("Job", f.Job)
196		add("Script", f.ScriptLine)
197		add("Match", f.Match)
198		return facts
199	}
200	
201	// packageFact is "name version (kind)", leaving out what is unknown.
202	func packageFact(f scan.Finding) string {
203		if f.PkgName == "" {
204			return ""
205		}
206		out := f.PkgName
207		if f.Version != "" {
208			out += " " + f.Version
209		}
210		if kind := packageKind(f.Class); kind != "" {
211			out += " (" + kind + ")"
212		}
213		return out
214	}
215	
216	// findingFilePath is the absolute path of the finding's file under the scanned
217	// directory, or the reason it cannot be opened. It does no I/O: whether the file
218	// exists is for the viewer to say (Rule 130, "Not knowing"). A path that leaves
219	// the target, by a parent segment or an absolute path elsewhere, is refused.
220	func findingFilePath(f scan.Finding, target string, onDisk bool) (string, shortcut.Availability) {
221		if !onDisk {
222			return "", shortcut.Unavailable(reasonFileNotOnDisk)
223		}
224		if f.File == "" {
225			return "", shortcut.Unavailable(reasonNoFile)
226		}
227		root := filepath.Clean(target)
228		file := filepath.ToSlash(f.File)
229		var path string
230		switch {
231		case file == scanMount || strings.HasPrefix(file, scanMount+"/"):
232			path = filepath.Join(root, filepath.FromSlash(strings.TrimPrefix(file, scanMount)))
233		case filepath.IsAbs(f.File):
234			path = filepath.Clean(f.File)
235		default:
236			path = filepath.Join(root, filepath.FromSlash(file))
237		}
238		rel, err := filepath.Rel(root, path)
239		if err != nil || rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
240			return "", shortcut.Unavailable(reasonFileOutsideTarget)
241		}
242		return path, shortcut.Availability{}
243	}
244	
245	// sameFinding says whether a and b are one finding across a re-scan: the line
246	// is not compared, the fix itself moves it.
247	func sameFinding(a, b scan.Finding) bool {
248		return a.Source == b.Source &&
249			remediation.RuleKey(a.ID) == remediation.RuleKey(b.ID) &&
250			a.File == b.File && a.PkgName == b.PkgName && a.Version == b.Version &&
251			instanceOf(a) == instanceOf(b)
252	}
253	
254	// fixAction says how to show f.FixCommand: ("Run", cmd) for a real command,
255	// ("", instruction) for a sentence such as "Update pkg to 1.2", ("", "") when
256	// there is none.
257	func fixAction(f scan.Finding) (label, text string) {
258		switch {
259		case f.FixCommand == "":
260			return "", ""
261		case scan.IsFixInstruction(f):
262			return "", f.FixCommand
263		}
264		return "Run", f.FixCommand
265	}
