245	
246	// packageKind says what has to move to clear a vulnerability, from the class
247	// Trivy reported. Empty for a result cached before the class was recorded: it
248	// is unknown, and is not shown rather than guessed.
249	func packageKind(class string) string {
250		switch class {
251		case scan.ClassOSPackages:
252			return "Base image package"
253		case scan.ClassLangPackages:
254			return "Application dependency"
255		}
256		return ""
257	}
