91			"charts/api/Chart.yaml":               "apiVersion: v2\nname: webapp\nversion: 0.1.0\n",
92			"charts/api/templates/deploy.yaml":    "kind: {{ .Values.kind }}\n",
93			"k8s/base/kustomization.yaml":         "resources:\n  - deploy.yaml\n",
94			"k8s/base/deploy.yaml":                "apiVersion: apps/v1\nkind: Deployment\nmetadata:\n  name: worker\n",
