136	// k8sSchemaFor is k8sSchema validated against one release.
137	func k8sSchemaFor(version string) ScanOptions {
138		opts := k8sSchema()
139		opts.Tools.Kubeconform.KubernetesVersion = version
140		return opts
141	}
