181	// A chart that does not render is a finding, not a failed scan — helm lint
182	// only warns about a missing dependency, and it is the render that fails.
183	func TestAChartThatDoesNotRenderIsAFinding(t *testing.T) {
184		isolateHome(t)
185		repo := renderRepo(t)
186		renderRunner(t, stageReply{err: &exitError{Code: 1,
187			Stderr: "Error: found in Chart.yaml, but missing in charts/ directory: redis\nmore"}})
188	
189		result, _ := newScannerWithDeps(k8sSchema(), renderingDeps()).
190			Scan(t.Context(), repo, TargetDirectory)
191	
192		var render *Finding
193		for i, f := range result.Findings {
194			if f.ID == K8sRenderID {
195				render = &result.Findings[i]
196			}
197		}
198		if render == nil {
199			t.Fatalf("no render finding among %+v", result.Findings)
200		}
201		if render.File != "charts/api/Chart.yaml" || !strings.HasSuffix(render.Title, "missing in charts/ directory: redis") {
202			t.Errorf("render finding = %q in %q", render.Title, render.File)
203		}
204		if len(result.Errors) != 0 {
205			t.Errorf("errors = %v, want none: the scan itself did not fail", result.Errors)
206		}
207	}
