128	// detailsHeader is the severity and ID, then the title on one line: a title can
129	// carry a whole stderr line, and the Message below has the rest.
130	func (m Model) detailsHeader(f scan.Finding, t detailsText) []string {
131		sev := string(f.Severity)
132		header := m.getSeverityStyle(f.Severity).Render(sev) + theme.Bg(" ") +
133			theme.TitleStyle.Render(oneLine(f.ID, t.width-ansi.StringWidth(sev)-1))
134		title := oneLine(shortPaths(f.Title, m.scanTarget()), t.width)
135		return []string{header, t.text.Render(title)}
136	}
137	
138	// detailsFix is the Fix block: the status in words, then, with no blank line
139	// between them, where the finding is, what to do, the command to run and what the
140	// fix does. It is written in ColorText alone (DEVDESK-751, AC7): ColorDim, the
141	// sub-title and the warning colours fall under 4.5:1 on several shipped themes,
142	// so the word "Warning:" carries the warning.
143	func (m Model) detailsFix(f scan.Finding, t detailsText) []string {
144		status := fixStatusOf(f, m.targetOnDisk())
145		lines := t.field("Fix: ", status.Label(), t.text)
146		lines = append(lines, m.detailsWhere(f, t)...)
147		lines = append(lines, t.list("Do: ", fixSteps(f), f.Resolution, t.text)...)
148		lines = append(lines, detailsRun(f, t)...)
149		lines = append(lines, t.field("Effect: ", status.Effect, t.text)...)
150		return append(lines, t.field("Warning: ", status.Warning, t.text)...)
151	}
152	
153	// detailsWhere is the file, then the other facts that place the finding, each on
154	// its own line under the first.
155	func (m Model) detailsWhere(f scan.Finding, t detailsText) []string {
156		const label = "Where: "
157		facts := whereFacts(f, m.scanTarget())
158		if len(facts) == 0 {
159			return nil
160		}
161		first := facts[0].Value
162		if facts[0].Label != "File" {
163			first = facts[0].Label + ": " + first
164		}
165		lines := t.field(label, first, t.text)
166		for _, fc := range facts[1:] {
167			lines = append(lines, t.fieldAt(ansi.StringWidth(label), fc.Label+": ", fc.Value, t.text)...)
168		}
169		return lines
170	}
171	
172	// detailsRun is the command on one line, cut when it is wider than the column:
173	// the copy key puts the whole of it on the clipboard.
174	func detailsRun(f scan.Finding, t detailsText) []string {
175		const label = "Run: "
176		cmd, ok := runCommand(f)
177		if !ok {
178			return nil
179		}
180		return []string{t.heading(label) + t.text.Render(oneLine("$ "+cmd, t.width-ansi.StringWidth(label)))}
181	}
182	
183	// detailsWhy is the reason the finding matters: the scanner's description, the
184	// Pod Security profile, where the finding comes from and its type.
185	func (m Model) detailsWhy(f scan.Finding, t detailsText) []string {
186		var lines []string
187		if strings.TrimSpace(f.Description) != "" {
188			lines = t.block(f.Description, t.text)
189		}
190		lines = append(lines, t.field("Pod Security: ", pssLabel(f), t.text)...)
191		lines = append(lines, t.field("Source: ", f.Source, t.text)...)
192		lines = append(lines, t.field("Type: ", f.IaCType, t.text)...)
193		if len(lines) == 0 {
194			return nil
195		}
196		return append([]string{t.heading("Why:")}, lines...)
197	}
198	
199	// detailsOutput is what the scanner said about this instance, capped: the start
200	// of it is what tells two findings of one rule apart, and the rest is in the log.
201	// A message that only repeats the title or the description adds nothing.
202	func (m Model) detailsOutput(f scan.Finding, t detailsText) []string {
203		msg := strings.TrimSpace(f.Message)
204		if msg == "" || msg == strings.TrimSpace(f.Title) || msg == strings.TrimSpace(f.Description) {
205			return nil
206		}
207		lines, hidden := cappedLines(dropBlankLines(shortPaths(msg, m.scanTarget())), t.width, maxMessageLines)
208		if len(lines) == 0 {
209			return nil
210		}
211		out := []string{t.heading("Output:")}
212		for _, line := range lines {
213			out = append(out, t.text.Render(line))
214		}
215		if more := moreLines(hidden); more != "" {
216			out = append(out, theme.DimStyle.Render(more))
217		}
218		return out
219	}
220	
221	// detailsReferences are the reference URLs, one per line.
222	func (m Model) detailsReferences(f scan.Finding, t detailsText) []string {
223		if len(f.References) == 0 {
224			return nil
225		}
226		lines := []string{t.heading("Refs:")}
227		for _, ref := range f.References {
228			lines = append(lines, t.indented("  ", ref, t.text)...)
229		}
230		return lines
231	}
