99	// renderRunner answers each tool of the schema stage the way it answered for
100	// real, keyed on what the invocation is rather than on its order.
101	func renderRunner(t *testing.T, helmTemplate stageReply) *scriptedRunner {
102		t.Helper()
103		lint, _ := os.ReadFile(filepath.Join("testdata", "helm_lint_broken.txt"))
104		rendered, _ := os.ReadFile(filepath.Join("testdata", "helm_template_api.yaml"))
105		if helmTemplate.stdout == "" && helmTemplate.err == nil {
106			helmTemplate.stdout = string(rendered)
107		}
108		invalid := `{"resources":[{"filename":"stdin","kind":"Deployment","name":"%s","version":"apps/v1",
109		  "status":"statusInvalid","validationErrors":[{"path":"/spec/replicas","msg":"got string, want null or integer"}]}]}`
110		r := &scriptedRunner{}
111		r.reply = func(tc toolCmd) ([]byte, error) {
112			args := strings.Join(tc.Args, " ")
113			switch {
114			case strings.HasPrefix(args, "lint "):
115				return []byte(strings.ReplaceAll(string(lint), "charts/broken", "charts/api")), nil
116			case strings.HasPrefix(args, "template "):
117				return []byte(helmTemplate.stdout), helmTemplate.err
118			case strings.HasPrefix(args, "build "):
119				return []byte("apiVersion: apps/v1\nkind: Deployment\nmetadata:\n  name: worker\n"), nil
120			case strings.HasSuffix(args, " -") && strings.Contains(string(tc.Stdin), "release-name-web"):
121				return []byte(strings.ReplaceAll(invalid, "%s", "release-name-web")), &exitError{Code: 1}
122			case strings.HasSuffix(args, " -"):
123				return []byte(strings.ReplaceAll(invalid, "%s", "worker")), &exitError{Code: 1}
124			}
125			t.Errorf("unexpected invocation: %s", tc)
126			return nil, nil
127		}
128		useRunner(t, r)
129		return r
130	}
