// parseGitleaksOutput parses Gitleaks JSON output into findings
func parseGitleaksOutput(data []byte) ([]Finding, error) {
	var gitleaksFindings []GitleaksFinding
	if err := json.Unmarshal(data, &gitleaksFindings); err != nil {
		return nil, fmt.Errorf("failed to parse gitleaks output: %w", err)
	}

	findings := make([]Finding, 0, len(gitleaksFindings))

	for _, gf := range gitleaksFindings {
		findings = append(findings, Finding{
			ID:          gf.RuleID,
			Title:       fmt.Sprintf("Secret detected: %s", gf.RuleID),
			Description: gf.Description,
			Severity:    SeverityHigh, // Secrets are always high severity
			Source:      "gitleaks",
			File:        gf.File,
			Line:        gf.StartLine,
			Match:       maskSecret(gf.Secret),
			Fingerprint: gf.Fingerprint,
		})
	}

	return findings, nil
}

// GetGitleaksCommand returns the command that would be executed, for display
// and logging. It is built by the same builder as the executed command, so the
// two cannot drift apart — except for the report path on native Windows,
// where RunGitleaks substitutes a fresh temp file per run (gitleaksReportFileTarget):
// showing one here would be meaningless since it is discarded unread, and
// creating it would leak a file for every logged command.
func GetGitleaksCommand(target string, tool ToolSpec, history bool, configPath string) string {
	return gitleaksArgs(target, tool, history, configPath, "").String()
}

// AddToGitleaksIgnore adds a finding to the .gitleaksignore file in the target directory
// Returns nil if already present (silently skips duplicates)
func AddToGitleaksIgnore(targetDir string, finding Finding) (err error) {
	var findings []Finding

	for _, result := range report.Results {
		// Process vulnerabilities
		for _, vuln := range result.Vulnerabilities {
			refs := mergeRefs(vuln.PrimaryURL, vuln.References)

			// Build a fix command suggestion when a fixed version is known
			fixCmd := trivyFixCommand(result.Type, vuln)

			findings = append(findings, Finding{
				ID:          vuln.VulnerabilityID,
				Title:       vuln.Title,
				Description: vuln.Description,
				Severity:    parseSeverity(vuln.Severity),
				Source:      "trivy",
				File:        result.Target,
				PkgName:     vuln.PkgName,
				Version:     vuln.InstalledVersion,
				FixedIn:     vuln.FixedVersion,
				Class:       result.Class,
				Ecosystem:   result.Type,
				References:  refs,
				FixCommand:  fixCmd,
			})
		}

		// Process secrets found by Trivy.
		//
		// The report has carried these since TrivySecret was declared; nothing
		// read them, so a secret Trivy found was parsed and dropped. Only the
		// secret stage asks for them (--scanners secret), so there is no risk of
		// the vulnerability stage returning the same finding twice.
		for _, secret := range result.Secrets {
			findings = append(findings, Finding{
				ID:          secret.RuleID,
				Title:       secret.Title,
				Description: secret.Category,
				Severity:    parseSeverity(secret.Severity),
				Source:      SourceTrivySecret,
				File:        result.Target,
				Line:        secret.StartLine,
				Match:       maskSecret(secret.Match),
			})
		}

		// Process licenses found by Trivy
		for _, license := range result.Licenses {
			findings = append(findings, Finding{
				ID:          license.Name,
				Title:       fmt.Sprintf("%s (%s)", license.PkgName, license.Name),
				Description: fmt.Sprintf("License category: %s", license.Category),
				Severity:    parseSeverity(license.Severity),
				Source:      "trivy-license",
				File:        license.FilePath,
				PkgName:     license.PkgName,
			})
		}

		// Process misconfigurations found by Trivy
		for _, misconf := range result.Misconfigurations {
			findings = append(findings, Finding{
				ID:          firstNonEmpty(misconf.AVDID, misconf.ID),
				Title:       misconf.Title,
				Description: misconf.Desc,
				Severity:    parseSeverity(misconf.Severity),
				Source:      "trivy-misconfig",
				File:        result.Target,
				Line:        misconf.CauseMetadata.StartLine,
				EndLine:     misconf.CauseMetadata.EndLine,
				Message:     misconf.Message,
				Status:      misconf.Status,
				// The result's type, not the misconfiguration's own: that one
				// is a label ("Kubernetes Security Check"), this one the
				// dialect ("kubernetes").
				IaCType:    strings.ToLower(result.Type),
				Resolution: misconf.Resolution,
				References: mergeRefs(misconf.PrimaryURL, misconf.References),
			})
		}
