// Scan runs its stages concurrently against one runner, so a test says what
// each stage answers rather than what the next call answers.

type stageReply struct {
	stdout string
	err    error
}

// stageOf names the stage an invocation belongs to, from the invocation alone —
// which is the only thing the runner sees.
//
// "secret" and "trivy-secret" are separate: secret scanning is the one option
// served by both tools, Gitleaks over git history and Trivy over the target's
// content, and only Trivy's half applies to an image.
func stageOf(tc toolCmd) string {
	s := tc.String()
	switch {
	case strings.Contains(s, "--scanners license"):
		return "license"
	case strings.Contains(s, "--scanners misconfig"):
		return "misconfig"
	case strings.Contains(s, "--scanners secret"):
		return "trivy-secret"
	case strings.HasPrefix(s, "gitleaks"):
		return "secret"
	case strings.Contains(s, "-output json -strict"):
		return "k8s-schema"
	default:
		return "vuln"
	}
}

func byStage(t *testing.T, replies map[string]stageReply) *scriptedRunner {
	t.Helper()
	r := &scriptedRunner{}
	r.reply = func(tc toolCmd) ([]byte, error) {
		stage := stageOf(tc)
		reply, scripted := replies[stage]
		if !scripted {
			t.Errorf("the %s stage ran although nothing was scripted for it: %s", stage, tc)
		}
		return []byte(reply.stdout), reply.err
	}
	useRunner(t, r)
	return r
}

// stagesRun reports which stages the runner was actually asked to execute.
func stagesRun(r *scriptedRunner) []string {
	r.mu.Lock()
	defer r.mu.Unlock()
	seen := make([]string, 0, len(r.calls))
	for _, c := range r.calls {
		seen = append(seen, stageOf(c))
	}
	sort.Strings(seen)
	return seen
}

// binaries is a report in which these tools run from a binary on PATH, and
// every other tool is missing.
func binaries(ids ...ToolID) Report {
	r := Report{Tools: map[ToolID]ToolStatus{}, EngineAvailable: true}
	for _, id := range ids {
		tool, _ := ToolByID(id)
		r.Tools[id] = ToolStatus{Available: true, Source: ToolSourceBinary, Image: tool.DefaultImage}
	}
	return r
}

// without is the report with one tool gone. The map is copied: a report is a
// value, and a test that removes a tool must not remove it from another's.
func (r Report) without(id ToolID) Report {
	tools := make(map[ToolID]ToolStatus, len(r.Tools))
	for k, v := range r.Tools {
		tools[k] = v
	}
	delete(tools, id)
	r.Tools = tools
	return r
}

func everyTool() Report { return binaries(ToolTrivy, ToolGitleaks) }

// categories turns these categories on, each with its default tools, and
// every other one off.
func categories(ids ...CategoryID) config.ScanCategories {
	c := config.DefaultScanCategories()
	c.Vuln.Enabled, c.Secret.Enabled = false, false
	for _, id := range ids {
		c.Category(string(id)).Enabled = true
	}
	return c
}

// scanFor asks for these categories and nothing else.
func scanFor(ids ...CategoryID) ScanOptions { return ScanOptions{Categories: categories(ids...)} }

// k8sSchema is Misconfiguration with kubeconform and its renderers ticked and
// Trivy not: the schema stage alone.
func k8sSchema() ScanOptions {
	c := categories()
	c.Misconfig = config.CategoryConfig{Enabled: true,
		Tools: []string{config.ToolKubeconform, config.ToolHelm, config.ToolKustomize}}
	return ScanOptions{Categories: c}
}

func everyStage() ScanOptions {
	return scanFor(CategoryIDVuln, CategoryIDSecret, CategoryIDLicense, CategoryIDMisconfig)
}

// recorder collects progress from the scan goroutines.
type recorder struct {
	mu      sync.Mutex
	updates []ProgressUpdate
// scriptedRunner stands in for the scanners. The reply is chosen per invocation
// so one scan can be given a different answer for each stage it runs, and the
// calls are recorded so a test can say which tool was asked what.
//
// It is locked because Scanner.Scan runs its stages concurrently.
type scriptedRunner struct {
	mu       sync.Mutex
	calls    []toolCmd
	progress []string
	reply    func(toolCmd) ([]byte, error)
}

func (r *scriptedRunner) Run(_ context.Context, tc toolCmd, progressFn func(string)) ([]byte, error) {
	r.mu.Lock()
	r.calls = append(r.calls, tc)
	lines := r.progress
	r.mu.Unlock()

	if progressFn != nil {
		for _, line := range lines {
			progressFn(line)
		}
	}
	return r.reply(tc)
}

func (r *scriptedRunner) commands() []string {
	r.mu.Lock()
	defer r.mu.Unlock()
	out := make([]string, 0, len(r.calls))
	for _, c := range r.calls {
		out = append(out, c.String())
	}
	return out
}

// commandForStage returns the invocation of one stage, or "" if it never ran.
//
// Scan runs its stages concurrently, so calls are recorded in completion order:
// a test that wants one scanner's command has to name the stage. Taking the
// last command that merely looked like Trivy is how this went: two stages
// invoke Trivy, and whichever finished second won.
func (r *scriptedRunner) commandForStage(stage string) string {
	r.mu.Lock()
	defer r.mu.Unlock()
	for _, c := range r.calls {
		if stageOf(c) == stage {
			return c.String()
		}
	}
	return ""
}

func (r *scriptedRunner) count() int {
	r.mu.Lock()
	defer r.mu.Unlock()
	return len(r.calls)
}

// useRunner swaps the package runner for the duration of the test. Production
// never reassigns it, so tests that do must not run in parallel.
func useRunner(t *testing.T, r commandRunner) {
	t.Helper()
	previous := runner
	runner = r
	t.Cleanup(func() { runner = previous })
}

// answering builds a runner that gives every invocation the same reply.
func answering(t *testing.T, stdout string, err error) *scriptedRunner {
	t.Helper()
	r := &scriptedRunner{reply: func(toolCmd) ([]byte, error) { return []byte(stdout), err }}
	useRunner(t, r)
	return r
}

