// The scan itself runs Trivy and Gitleaks in containers, and the browser and
// cache commands reach the desktop and the disk. No test executes one: results,
// progress updates and dependency checks are fed in as messages, and the
// assertions are on model state.
//
// These tests drive Update() and View() only — model.go is 1977 lines, the
// largest file in the project and due to be split, so assertions on its
// internals would pin the current layout.
//
// The form persists every toggle with config.Save, so HOME is redirected for
// the whole package: a test must not rewrite the developer's ~/.devdesk.

func TestMain(m *testing.M) {
	log.SetOutput(io.Discard)
	// No engine and no registry is reached from a test (§3.88).
	localImageDigests = func([]string) map[string][]string { return nil }
	checkImageUpdates = func([]string) map[string]imageupdate.Facts { return nil }
	// Nor cosign, through the Remediation tab's signature checks (§3.82).
	newPullDeps = func(*config.Config, *scan.Report) imagepull.Deps { return imagepull.Deps{} }
	// Nor the developer's own HTTPS_PROXY, which would add a footer warning to
	// every remediation scan (DEVDESK-583).
	containerForward = func() netproxy.Forward { return netproxy.Forward{} }
	// Nor the machine's clipboard, through the detail's Y (DEVDESK-751). A test
	// that copies installs its own recorder with stubClipboard; reaching this
	// one means a key wrote to the real clipboard.
	writeClipboard = func(text string) error {
		panic("DEVDESK-751: a test wrote to the real clipboard: " + text)
	}

	home, err := os.MkdirTemp("", "devdesk-security-test")
	if err != nil {
		log.SetOutput(os.Stderr)
		panic(err)
	}
	_ = os.Setenv("HOME", home)
	_ = os.Setenv("USERPROFILE", home)

	code := m.Run()

	_ = os.RemoveAll(home)
	log.SetOutput(os.Stderr)
	os.Exit(code)
}

