2	
3	import (
4		"go/ast"
5		"go/parser"
6		"go/token"
7		"os"
8		"slices"
9		"strconv"
10		"strings"
11		"testing"
12	)
13	
14	// DEVDESK-751 (step 6, AC5): DevDesk copies the command under Run and never runs
15	// it. The command is text the scanner wrote about a package: handing it to a
16	// shell would turn a finding into code execution. The guard reads the sources of
17	// this package and fails, naming the file and the function, when:
18	//
19	//	R1  a file that imports os/exec (or the exec wrapper) also reads the command;
20	//	R2  one function both reads the command and starts a process;
21	//	R3  a function reachable from the copy path (copyFixCommand, runCommand, the Run
22	//	    line) starts a process.
23	//
24	// "Reads the command" is: the identifier runCommand, a selector .FixCommand, or a
25	// FixCommandCopiedMsg. "Starts a process" is a call on exec, teaexec or syscall,
26	// os.StartProcess, or tea.Exec / tea.ExecProcess.
27	//
28	// Limits, stated: it follows calls by name inside this package, so a call through
29	// a function value or the writeClipboard seam is not followed (the clipboard
30	// package pipes the text to the clipboard tool's stdin, never as an argument),
31	// and a process started from another package is out of its sight.
32	
33	// copyPathRoots are where the copied command lives. They must exist: a rename
34	// would otherwise make R3 pass on nothing.
35	var copyPathRoots = []string{"copyFixCommand", "runCommand", "detailsRun"}
36	
37	type sourceFile struct {
38		name string
39		file *ast.File
40	}
41	
42	func parseSources(t *testing.T, sources map[string]string) []sourceFile {
43		t.Helper()
44		fset := token.NewFileSet()
45		var out []sourceFile
46		names := make([]string, 0, len(sources))
47		for name := range sources {
48			names = append(names, name)
49		}
50		slices.Sort(names)
51		for _, name := range names {
52			f, err := parser.ParseFile(fset, name, sources[name], 0)
53			if err != nil {
54				t.Fatalf("parse %s: %v", name, err)
55			}
56			out = append(out, sourceFile{name, f})
57		}
58		return out
59	}
60	
61	func packageSources(t *testing.T) map[string]string {
62		t.Helper()
63		entries, err := os.ReadDir(".")
64		if err != nil {
65			t.Fatal(err)
66		}
67		sources := map[string]string{}
68		for _, e := range entries {
69			name := e.Name()
70			if !strings.HasSuffix(name, ".go") || strings.HasSuffix(name, "_test.go") {
71				continue
72			}
73			b, err := os.ReadFile(name)
74			if err != nil {
75				t.Fatal(err)
76			}
77			sources[name] = string(b)
78		}
79		return sources
80	}
81	
82	// readsCommand reports whether a node mentions the command.
83	func readsCommand(n ast.Node) bool {
84		found := false
85		ast.Inspect(n, func(x ast.Node) bool {
86			switch v := x.(type) {
87			case *ast.Ident:
88				if v.Name == "runCommand" || v.Name == "FixCommandCopiedMsg" {
89					found = true
90				}
91			case *ast.SelectorExpr:
92				if v.Sel.Name == "FixCommand" {
93					found = true
94				}
95			}
96			return !found
97		})
98		return found
99	}
100	
101	// startsProcess reports whether a node calls something that starts a process.
102	func startsProcess(n ast.Node) bool {
103		found := false
104		ast.Inspect(n, func(x ast.Node) bool {
105			call, ok := x.(*ast.CallExpr)
106			if !ok {
107				return !found
108			}
109			sel, ok := call.Fun.(*ast.SelectorExpr)
110			if !ok {
111				return !found
112			}
113			pkg, ok := sel.X.(*ast.Ident)
114			if !ok {
115				return !found
116			}
117			switch {
118			case pkg.Name == "exec" || pkg.Name == "teaexec":
119				found = true
120			case pkg.Name == "syscall" && (sel.Sel.Name == "Exec" || sel.Sel.Name == "ForkExec"):
121				found = true
122			case pkg.Name == "os" && sel.Sel.Name == "StartProcess":
123				found = true
124			case pkg.Name == "tea" && (sel.Sel.Name == "Exec" || sel.Sel.Name == "ExecProcess"):
125				found = true
126			}
127			return !found
128		})
129		return found
130	}
131	
132	func importsExec(f *ast.File) bool {
133		for _, imp := range f.Imports {
134			path, err := strconv.Unquote(imp.Path.Value)
135			if err == nil && (path == "os/exec" || strings.HasSuffix(path, "/teaexec")) {
136				return true
137			}
138		}
139		return false
140	}
141	
142	// neverRunViolations is the guard itself, over parsed sources.
143	func neverRunViolations(files []sourceFile, roots []string) []string {
144		var out []string
145		funcs := map[string][]*ast.FuncDecl{}
146		owner := map[*ast.FuncDecl]string{}
147		for _, sf := range files {
148			reads := false
149			for _, decl := range sf.file.Decls {
150				fn, ok := decl.(*ast.FuncDecl)
151				if !ok || fn.Body == nil {
152					continue
153				}
154				funcs[fn.Name.Name] = append(funcs[fn.Name.Name], fn)
155				owner[fn] = sf.name
156				read := readsCommand(fn.Body)
157				reads = reads || read
158				if read && startsProcess(fn.Body) {
159					out = append(out, sf.name+": "+fn.Name.Name+" reads the command and starts a process (R2)")
160				}
161			}
162			if reads && importsExec(sf.file) {
163				out = append(out, sf.name+" reads the command and imports os/exec or the exec wrapper (R1)")
164			}
165		}
166	
167		seen := map[string]bool{}
168		queue := slices.Clone(roots)
169		for len(queue) > 0 {
170			name := queue[0]
171			queue = queue[1:]
172			if seen[name] {
173				continue
174			}
175			seen[name] = true
176			for _, fn := range funcs[name] {
177				if startsProcess(fn.Body) {
178					out = append(out, owner[fn]+": "+name+" is on the copy path and starts a process (R3)")
179				}
180				ast.Inspect(fn.Body, func(x ast.Node) bool {
181					switch c := x.(type) {
182					case *ast.CallExpr:
183						switch f := c.Fun.(type) {
184						case *ast.Ident:
185							queue = append(queue, f.Name)
186						case *ast.SelectorExpr:
187							queue = append(queue, f.Sel.Name)
188						}
189					}
190					return true
191				})
192			}
193		}
194		return out
195	}
196	
197	func TestTheCopiedCommandIsNeverRun(t *testing.T) {
198		files := parseSources(t, packageSources(t))
199		declared := map[string]bool{}
200		for _, sf := range files {
201			for _, decl := range sf.file.Decls {
202				if fn, ok := decl.(*ast.FuncDecl); ok {
203					declared[fn.Name.Name] = true
204				}
205			}
206		}
207		for _, root := range copyPathRoots {
208			if !declared[root] {
209				t.Errorf("%s is not declared in a non-test file: the guard has nothing to follow, rename it in copyPathRoots", root)
210			}
211		}
212		for _, v := range neverRunViolations(files, copyPathRoots) {
213			t.Error(v)
214		}
215	}
216	
217	// The guard must be able to fail: each shape it forbids is fed to it.
218	func TestTheNeverRunGuardCatchesWhatItForbids(t *testing.T) {
219		const header = "package security\nimport (\n\"os/exec\"\n)\n"
220		tests := []struct {
221			name    string
222			src     string
223			roots   []string
224			wantHit string
225		}{
226			{"a command from the finding handed to exec", header + `
227	func a(f Finding) { exec.Command("sh", "-c", f.FixCommand).Run() }`, nil, "(R2)"},
228			{"the copied command handed to exec", header + `
229	func a(f Finding) { cmd, _ := runCommand(f); exec.Command(cmd).Run() }`, nil, "(R2)"},
230			{"a file that imports exec and reads the command elsewhere", header + `
231	func a(f Finding) string { return f.FixCommand }
232	func b() { exec.Command("ls").Run() }`, nil, "(R1)"},
233			{"the copy path calls a helper that starts a process", `package security
234	import "os/exec"
235	func copyFixCommand() { helper() }
236	func helper() { exec.Command("ls").Run() }`, []string{"copyFixCommand"}, "(R3)"},
237			{"the copy path hands the command to the terminal", `package security
238	func copyFixCommand(f Finding) { tea.ExecProcess(nil, nil) ; _ = f.FixCommand }`, []string{"copyFixCommand"}, "(R2)"},
239		}
240		for _, tc := range tests {
241			t.Run(tc.name, func(t *testing.T) {
242				got := neverRunViolations(parseSources(t, map[string]string{"x.go": tc.src}), tc.roots)
243				if !slices.ContainsFunc(got, func(v string) bool { return strings.Contains(v, tc.wantHit) }) {
244					t.Errorf("violations = %v, want one marked %s", got, tc.wantHit)
245				}
246			})
247		}
248	
249		benign := `package security
250	func copyFixCommand(f Finding) { go writeClipboard(f.FixCommand) }
251	func other() { exec.Command("git", "status").Run() }`
252		if got := neverRunViolations(parseSources(t, map[string]string{"x.go": benign}), []string{"copyFixCommand"}); len(got) != 0 {
253			t.Errorf("a copy that starts nothing is reported: %v", got)
254		}
255	}
