132	// withoutControlSpace makes a scanner's text safe for the terminal: an escape
133	// sequence (CSI, OSC) is removed whole, a tab becomes four spaces, which is how
134	// the renderer lays it out, and every other control character (C0, C1, a carriage
135	// return) is dropped, as are the characters with no visible form that reorder or
136	// hide text (bidi and zero-width marks, line and paragraph separators). A line
137	// feed stays: the callers decide what a line is.
138	func withoutControlSpace(text string) string {
139		text = ansi.Strip(text)
140		var b strings.Builder
141		b.Grow(len(text))
142		for _, r := range text {
143			switch {
144			case r == '\t':
145				b.WriteString("    ")
146			case r == '\n':
147				b.WriteRune(r)
148			case unicode.IsControl(r), unicode.In(r, unicode.Zl, unicode.Zp):
149			case unicode.Is(unicode.Cf, r) && r != '\u200c' && r != '\u200d':
150				// The joiners stay: emoji sequences need them.
151			default:
