162	func normalizeText(text string, dropBlank bool) string {
163		text = withoutControlSpace(text)
164		var out []string
165		for _, line := range strings.Split(text, "\n") {
166			line = strings.TrimRight(line, " ")
167			blank := line == ""
168			switch {
169			case blank && (dropBlank || len(out) == 0 || out[len(out)-1] == ""):
170			default:
171				out = append(out, line)
172			}
173		}
174		for len(out) > 0 && out[len(out)-1] == "" {
