103		text = strings.TrimRight(text, " \t\r\n")
104		lines = strings.Split(ansi.Wrap(text, max(min(width, maxMessageWidth), 1), ""), "\n")
105		if len(lines) > maxLines {
106			return lines[:maxLines], len(lines) - maxLines
107		}
108		return lines, 0
109	}
110	
111	// moreLines is the marker after a capped text, "" when nothing was left out.
112	func moreLines(n int) string {
113		switch {
114		case n <= 0:
115			return ""
116		case n == 1:
117			return "… 1 more line"
118		}
119		return fmt.Sprintf("… %d more lines", n)
120	}
121	
122	// scrollPosition is "Lines a-b of N" when the content is taller than the
123	// viewport, "" otherwise.
124	func scrollPosition(offset, visible, total int) string {
125		if visible <= 0 || total <= visible {
126			return ""
127		}
128		offset = max(offset, 0)
129		return fmt.Sprintf("Lines %d-%d of %d", offset+1, min(offset+visible, total), total)
130	}
131	
132	// withoutControlSpace makes a scanner's text safe for the terminal: an escape
133	// sequence (CSI, OSC) is removed whole, a tab becomes four spaces, which is how
134	// the renderer lays it out, and every other control character (C0, C1, a carriage
135	// return) is dropped, as are the characters with no visible form that reorder or
136	// hide text (bidi and zero-width marks, line and paragraph separators). A line
137	// feed stays: the callers decide what a line is.
138	func withoutControlSpace(text string) string {
139		text = ansi.Strip(text)
140		var b strings.Builder
141		b.Grow(len(text))
142		for _, r := range text {
143			switch {
144			case r == '\t':
145				b.WriteString("    ")
146			case r == '\n':
147				b.WriteRune(r)
148			case unicode.IsControl(r), unicode.In(r, unicode.Zl, unicode.Zp):
149			case unicode.Is(unicode.Cf, r) && r != '\u200c' && r != '\u200d':
150				// The joiners stay: emoji sequences need them.
151			default:
152				b.WriteRune(r)
153			}
154		}
155		return b.String()
156	}
157	
158	// normalizeText makes a scanner's text safe to lay out: a tab or a carriage
159	// return has no width the viewport and the terminal agree on, trailing spaces
160	// are noise, and a run of blank lines is one blank line. dropBlank removes the
161	// blank lines altogether (a stderr, where they separate nothing).
162	func normalizeText(text string, dropBlank bool) string {
163		text = withoutControlSpace(text)
164		var out []string
165		for _, line := range strings.Split(text, "\n") {
166			line = strings.TrimRight(line, " ")
167			blank := line == ""
168			switch {
169			case blank && (dropBlank || len(out) == 0 || out[len(out)-1] == ""):
170			default:
171				out = append(out, line)
172			}
173		}
174		for len(out) > 0 && out[len(out)-1] == "" {
175			out = out[:len(out)-1]
176		}
177		return strings.Join(out, "\n")
178	}
179	
180	// dropBlankLines is normalizeText without any blank line.
181	func dropBlankLines(text string) string { return normalizeText(text, true) }
182	
183	// detailsText lays text out for the finding detail: every line it returns is
184	// styled on the theme background and spans at most width cells, measured with
185	// x/ansi as the viewport does.
186	type detailsText struct {
187		width int            // cells a line may span
188		text  lipgloss.Style // ordinary text
189		dim   lipgloss.Style // secondary text
190	}
191	
192	func newDetailsText(width int) detailsText {
193		return detailsText{
194			width: width,
195			text:  lipgloss.NewStyle().Background(theme.ColorBackground).Foreground(theme.ColorText),
196			dim:   theme.DimStyle,
197		}
198	}
199	
200	// block wraps text at the full width, one styled line per entry.
201	func (t detailsText) block(text string, style lipgloss.Style) []string {
202		return t.indented("", text, style)
203	}
204	
205	// indented wraps text under a prefix of spaces.
206	func (t detailsText) indented(prefix, text string, style lipgloss.Style) []string {
207		text = normalizeText(text, false)
208		if text == "" {
209			return nil
210		}
211		var lines []string
212		for _, line := range t.wrapped(text, t.width-ansi.StringWidth(prefix)) {
213			if line == "" {
214				lines = append(lines, "")
215				continue
216			}
217			lines = append(lines, margin(ansi.StringWidth(prefix))+style.Render(line))
218		}
219		return lines
220	}
221	
222	// wrapped is text broken into lines of at most room cells, trailing spaces gone.
223	func (t detailsText) wrapped(text string, room int) []string {
224		lines := strings.Split(ansi.Wrap(text, max(room, 1), ""), "\n")
225		for i, line := range lines {
226			lines[i] = strings.TrimRight(line, " ")
227		}
228		return lines
229	}
230	
231	// margin is n cells of the theme background, "" for none.
232	func margin(n int) string {
233		if n <= 0 {
234			return ""
235		}
236		return theme.Bg(strings.Repeat(" ", n))
237	}
238	
239	// heading is a label on a line of its own.
240	func (t detailsText) heading(label string) string {
241		return theme.DetailLabelStyle.Render(label)
242	}
243	
244	// field is a label and its value, the value wrapped under itself. When the label
245	// leaves too little room for the value, the value goes on the lines below.
246	func (t detailsText) field(label, value string, style lipgloss.Style) []string {
247		return t.fieldAt(0, label, value, style)
248	}
249	
250	// fieldAt is field after indent cells of margin.
251	func (t detailsText) fieldAt(indent int, label, value string, style lipgloss.Style) []string {
252		value = normalizeText(value, false)
253		if value == "" {
254			return nil
255		}
256		labelWidth := indent + ansi.StringWidth(label)
257		if t.width-labelWidth < minFieldValueWidth {
258			head := margin(indent) + t.heading(strings.TrimRight(label, " "))
259			return append([]string{head}, t.indented(strings.Repeat(" ", indent), value, style)...)
260		}
261		lines := t.wrapped(value, t.width-labelWidth)
262		out := make([]string, 0, len(lines))
263		for i, line := range lines {
264			line = style.Render(line)
265			if i == 0 {
266				out = append(out, margin(indent)+t.heading(label)+line)
267			} else {
268				out = append(out, margin(labelWidth)+line)
269			}
270		}
271		return out
272	}
273	
274	// list is a label, then numbered steps that hang under their own text, then a
275	// paragraph, all after the label's width. A step or paragraph with nothing to
276	// say is skipped; the label shares the first line.
277	func (t detailsText) list(label string, steps []string, paragraph string, style lipgloss.Style) []string {
278		room := t.width - ansi.StringWidth(label)
279		var body []string
280		for i, step := range steps {
281			number := fmt.Sprintf("%d. ", i+1)
282			for j, line := range t.wrapped(normalizeText(step, true), room-len(number)) {
283				if j > 0 {
284					line = strings.Repeat(" ", len(number)) + line
285				} else {
286					line = number + line
287				}
288				body = append(body, line)
289			}
290		}
291		if text := dropBlankLines(paragraph); text != "" {
292			body = append(body, t.wrapped(text, room)...)
293		}
294		out := make([]string, 0, len(body))
295		for i, line := range body {
296			if i == 0 {
297				out = append(out, t.heading(label)+style.Render(line))
298			} else {
299				out = append(out, margin(ansi.StringWidth(label))+style.Render(line))
300			}
301		}
302		return out
303	}
304	
305	// minFieldValueWidth is the least room a value needs beside its label.
306	const minFieldValueWidth = 12
