		Version:     f.Version,
		FixedIn:     f.FixedIn,
		Class:       f.Class,
		Ecosystem:   f.Ecosystem,
		IaCType:     f.IaCType,
		Resolution:  f.Resolution,
		References:  f.References,
		PSSProfile:  pssProfile,
	}
