// root, never run by DevDesk, absent for a container.
func TestTheScanResultSchemaExplainsStepsAndRepro(t *testing.T) {
	cs := connect(t, testEnv(nil))
	tools, err := cs.ListTools(t.Context(), nil)
	if err != nil {
		t.Fatalf("ListTools: %v", err)
	}
	for _, tool := range tools.Tools {
		if tool.Name != "scan_result" {
			continue
		}
		schema, ok := tool.OutputSchema.(map[string]any)
		if !ok {
			t.Fatalf("output schema is a %T", tool.OutputSchema)
		}
		text := strings.ToLower(schemaText(schema))
		for _, want := range []string{"\"steps\"", "\"repro\"", "root", "never runs", "container"} {
			if !strings.Contains(text, want) {
				t.Errorf("the scan_result schema lacks %s", want)
			}
		}
		if strings.Contains(text, "ran_from") {
			t.Error("the scan_result schema exposes ran_from")
		}
		return
	}
	t.Fatal("no scan_result tool")
}

func schemaText(v any) string {
	var b strings.Builder
	var walk func(any)
	walk = func(x any) {
		switch t := x.(type) {
		case map[string]any:
			for k, val := range t {
				b.WriteString("\"" + k + "\" ")
				walk(val)
			}
		case []any:
			for _, val := range t {
				walk(val)
			}
		case string:
			b.WriteString(t + " ")
		}
	}
	walk(v)
	return b.String()
}
